export interface WebVideoUploadSelection extends WebFileUploadSelection {
    /** Seconds, or null when the browser cannot decode this container/codec. */
    readonly duration: number | null;
}

export interface WebVideoUploadConfiguration extends WebNonvisualComponentOptions {
    readonly accept?: string;
    readonly enabled?: boolean;
    readonly title?: string;
    readonly descri?: string;
    readonly isPublic?: boolean;
    readonly chunkSizeBytes?: number;
    /** MiB (1024² bytes). Null disables the local file-size limit. */
    readonly maxFileSizeMB?: number | null;
    /** Null disables the local duration limit. */
    readonly maxDurationSeconds?: number | null;
}

export interface WebVideoUploadOptions {
    readonly title?: string;
    readonly descri?: string;
    readonly isPublic?: boolean;
    readonly signal?: AbortSignal;
}

export interface WebVideoUploadResumeOptions extends WebVideoUploadOptions {
    /** Supply a saved checkpoint after reload, after selecting the original file again. */
    readonly resumeToken?: import("@webrad/restgo-sdk").RestGoVideoResumeToken;
}

export type WebVideoUploadState = 'idle' | 'selecting' | 'selected' | 'hashing' | 'creating' | 'uploading' | 'paused' | 'finalizing' | 'uploaded' | 'waiting' | 'ready' | 'cancelling' | 'cancelled' | 'error';

export type WebVideoUploadProgressEventDetail = import("@webrad/restgo-sdk").RestGoVideoProgress;

export type WebVideoUploadProcessingEventDetail = import("@webrad/restgo-sdk").RestGoVideoDetails;

export type WebVideoUploadChangeEventDetail = WebVideoUploadSelection | null;

export type WebVideoUploadResult = import("@webrad/restgo-sdk").RestGoVideo;

export interface WebVideoUploadStateEventDetail {
    readonly previous: WebVideoUploadState;
    readonly state: WebVideoUploadState;
}

export interface WebVideoUploadCompleteEventDetail {
    readonly operation: 'upload' | 'processing' | 'cancel';
    readonly video: import("@webrad/restgo-sdk").RestGoVideo | null;
    readonly error: Error | null;
}

/** Nonvisual resumable uploader. Conversion runs on RestGo; waiting is explicit. */
export class WebVideoUpload extends WebNonvisualComponent {
    #private;
    title: string;
    descri: string;
    isPublic: boolean;
    constructor(configuration?: WebVideoUploadConfiguration);
    get accept(): string;
    set accept(value: string);
    get enabled(): boolean;
    set enabled(value: boolean);
    get maxFileSizeMB(): number | null;
    set maxFileSizeMB(value: number | null);
    get maxDurationSeconds(): number | null;
    set maxDurationSeconds(value: number | null);
    get chunkSizeBytes(): number;
    set chunkSizeBytes(value: number);
    get selectedFile(): File | null;
    get selection(): WebVideoUploadSelection | null;
    get uploadSession(): import("@webrad/restgo-sdk").RestGoVideoUploadSession | null;
    get resumeToken(): import("@webrad/restgo-sdk").RestGoVideoResumeToken | null;
    get video(): import("@webrad/restgo-sdk").RestGoVideo | null;
    get state(): WebVideoUploadState;
    get confirmedBytes(): number;
    get totalBytes(): number;
    get percentage(): number | null;
    get processingProgress(): number | null;
    get error(): Error | null;
    /** Opens the chooser from a user gesture. It never creates or sends an upload. */
    OpenFile(): Promise<WebVideoUploadSelection | null>;
    SendToRestGO(options?: WebVideoUploadOptions): Promise<import("@webrad/restgo-sdk").RestGoVideo>;
    Resume(options?: WebVideoUploadResumeOptions): Promise<import("@webrad/restgo-sdk").RestGoVideo>;
    /** Aborts only local upload I/O. The server session remains resumable. */
    Pause(): void;
    /** Explicitly cancels the open upload on RestGo. It does not cancel conversion jobs. */
    CancelUpload(): Promise<void>;
    WaitUntilReady(options?: import("@webrad/restgo-sdk").RestGoVideoWaitOptions): Promise<import("@webrad/restgo-sdk").RestGoVideo>;
    /** Clears local state and stops requests. No remote video/session is deleted. */
    Clear(): void;
    set onChange(handler: WebComponentEventHandler<this> | null);
    set onProgress(handler: WebComponentEventHandler<this> | null);
    set onStateChange(handler: WebComponentEventHandler<this> | null);
    set onUploadComplete(handler: WebComponentEventHandler<this> | null);
    set onProcessingProgress(handler: WebComponentEventHandler<this> | null);
    set onReady(handler: WebComponentEventHandler<this> | null);
    set onError(handler: WebComponentEventHandler<this> | null);
    set onComplete(handler: WebComponentEventHandler<this> | null);
    dispose(): void;
}
